#include <vector>

class Solution {
public:
    bool isZeroArray(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        int n = nums.size();
        std::vector<int> diff(n + 1, 0);
        for (auto& q : queries) {
            diff[q[0]]++;
            diff[q[1] + 1]--;
        }

        int curr = 0;
        for (int i = 0; i < n; ++i) {
            curr += diff[i];
            if (nums[i] > curr) return false;
        }
        return true;
    }
};

class Solution {
    public boolean isZeroArray(int[] nums, int[][] queries) {
        int n = nums.length;
        int[] diff = new int[n + 1];
        for (int[] q : queries) {
            diff[q[0]]++;
            diff[q[1] + 1]--;
        }

        int curr = 0;
        for (int i = 0; i < n; i++) {
            curr += diff[i];
            if (nums[i] > curr) return false;
        }
        return true;
    }
}

